import type { ScmInstallation, ScmInstallationSession } from '../../prisma/generated/client';
import { env } from '../env';
import { scmInstallationPresenter } from './scmInstallation';

export let presentScmInstallationSession = (
  session: ScmInstallationSession & {
    installation: ScmInstallation | null;
  }
) => ({
  id: session.id,
  url: `${env.service.ORIGIN_SERVICE_PUBLIC_URL}/origin/scm/installation-session/${session.id}`,

  status: session.installation
    ? ('completed' as const)
    : session.expiresAt < new Date()
      ? ('expired' as const)
      : ('pending' as const),

  installation: session.installation ? scmInstallationPresenter(session.installation) : null,

  createdAt: session.createdAt,
  expiresAt: session.expiresAt
});

import { notFoundError, ServiceError } from '@lowerdeck/error';
import { Paginator } from '@lowerdeck/pagination';
import { Service } from '@lowerdeck/service';
import type { Actor, Tenant } from '../../prisma/generated/client';
import { db } from '../db';

class ScmInstallationServiceImpl {
  async getScmInstallationById(d: { tenant: Tenant; scmInstallationId: string }) {
    let scmInstallation = await db.scmInstallation.findFirst({
      where: {
        id: d.scmInstallationId,
        tenantOid: d.tenant.oid
      },
      include: {
        backend: true
      }
    });
    if (!scmInstallation)
      throw new ServiceError(notFoundError('scm_installation', d.scmInstallationId));

    return scmInstallation;
  }

  async listScmInstallations(d: { tenant: Tenant; actor: Actor }) {
    return Paginator.create(({ prisma }) =>
      prisma(
        async opts =>
          await db.scmInstallation.findMany({
            ...opts,
            where: {
              tenantOid: d.tenant.oid,
              ownerActorOid: d.actor.oid
            },
            include: {
              backend: true
            }
          })
      )
    );
  }
}

export let scmInstallationService = Service.create(
  'scmInstallation',
  () => new ScmInstallationServiceImpl()
).build();

import { createHono } from '@lowerdeck/hono';
import { db } from '../db';
import { installationSessionHtml } from '../lib/templates/installationSession';
import { scmAuthService, scmBackendService, scmInstallationSessionService } from '../services';

export let scmInstallationSessionPublicController = createHono()
  .get('/:sessionId', async c => {
    let sessionId = c.req.param('sessionId');

    let session = await scmInstallationSessionService.getInstallationSessionPublic({
      sessionId
    });

    let tenant = await db.tenant.findUniqueOrThrow({ where: { oid: session.tenantOid } });
    let backends = await scmInstallationSessionService.getAvailableBackends({ tenant });

    return c.html(
      installationSessionHtml({
        sessionId: session.id,
        backends: backends.map(b => ({
          id: b.id,
          type: b.type,
          name: b.name,
          description: b.description,
          isDefault: b.isDefault
        }))
      })
    );
  })
  .get('/:sessionId/select-backend/:backendId', async c => {
    let sessionId = c.req.param('sessionId');
    let backendId = c.req.param('backendId');

    let session = await scmInstallationSessionService.getInstallationSessionPublic({
      sessionId
    });

    let tenant = await db.tenant.findUniqueOrThrow({ where: { oid: session.tenantOid } });
    let actor = await db.actor.findUniqueOrThrow({ where: { oid: session.ownerActorOid } });
    let backend = await scmBackendService.getScmBackendById({
      backendId,
      tenant
    });

    let authUrl = await scmAuthService.getAuthorizationUrl({
      tenant,
      actor,
      provider:
        backend.type === 'github' || backend.type === 'github_enterprise'
          ? 'github'
          : 'gitlab',
      backendId: backend.id,
      redirectUrl: '',
      state: session.state
    });

    return c.redirect(authUrl);
  });

import { v } from '@lowerdeck/validation';
import { presentScmInstallationSession } from '../presenters/scmInstallationSession';
import { actorService, scmInstallationSessionService } from '../services';
import { app } from './_app';
import { tenantApp } from './tenant';

export let scmInstallationSessionApp = tenantApp.use(async ctx => {
  let sessionId = ctx.body.sessionId;
  if (!sessionId) throw new Error('Session ID is required');

  let session = await scmInstallationSessionService.getInstallationSession({
    sessionId,
    tenant: ctx.tenant
  });

  return { session };
});

export let scmInstallationSessionController = app.controller({
  create: tenantApp
    .handler()
    .input(
      v.object({
        tenantId: v.string(),
        actorId: v.string(),
        redirectUrl: v.optional(v.string())
      })
    )
    .do(async ctx => {
      let actor = await actorService.getActorById({ id: ctx.input.actorId });

      let session = await scmInstallationSessionService.createInstallationSession({
        tenant: ctx.tenant,
        actor,
        redirectUrl: ctx.input.redirectUrl
      });

      return presentScmInstallationSession(session);
    }),

  get: scmInstallationSessionApp
    .handler()
    .input(
      v.object({
        tenantId: v.string(),
        sessionId: v.string()
      })
    )
    .do(async ctx => {
      return presentScmInstallationSession(ctx.session);
    })
});

import type { ScmBackend } from '../../prisma/generated/browser';
import type {
  ScmBackendSetupSession,
  ScmInstallationSession
} from '../../prisma/generated/client';
import { env } from '../env';
import { scmBackendPresenter } from './scmBackend';

export let presentScmBackendSetupSession = (
  session: ScmBackendSetupSession & {
    backend: ScmBackend | null;
    parentInstallationSession: ScmInstallationSession | null;
  }
) => ({
  object: 'origin#scmBackendSetupSession',
  id: session.id,
  type: session.type,
  url: `${env.service.ORIGIN_SERVICE_PUBLIC_URL}/origin/scm/backend-setup/${session.id}`,

  parentInstallationSessionId: session.parentInstallationSession?.id ?? null,

  status: session.backend
    ? ('completed' as const)
    : session.expiresAt < new Date()
      ? ('expired' as const)
      : ('pending' as const),

  backend: session.backend ? scmBackendPresenter(session.backend) : null,

  createdAt: session.createdAt,
  expiresAt: session.expiresAt
});

import { v } from '@lowerdeck/validation';
import { presentScmBackendSetupSession } from '../presenters/scmBackendSetupSession';
import { scmInstallationSessionService } from '../services';
import { app } from './_app';
