  return { session };
});

export let scmBackendSetupSessionController = app.controller({
  create: tenantApp
    .handler()
    .input(
      v.object({
        tenantId: v.string(),
        type: v.enumOf(['github_enterprise', 'gitlab_selfhosted']),
        parentInstallationSessionId: v.optional(v.string()),
        redirectUrl: v.optional(v.string())
      })
    )
    .do(async ctx => {
      let parentInstallationSession = ctx.input.parentInstallationSessionId
        ? await scmInstallationSessionService.getInstallationSession({
            sessionId: ctx.input.parentInstallationSessionId,
            tenant: ctx.tenant
          })
        : undefined;

      let session = await scmInstallationSessionService.createBackendSetupSession({
        tenant: ctx.tenant,
        type: ctx.input.type,
        parentInstallationSession,
        redirectUrl: ctx.input.redirectUrl
      });

      return presentScmBackendSetupSession(session);
    }),

  get: scmBackendSetupSessionApp
    .handler()
    .input(
      v.object({
        tenantId: v.string(),
        sessionId: v.string()
      })
    )
    .do(async ctx => {
      return presentScmBackendSetupSession(ctx.session);
    })
});

import { createHono, useValidatedBody } from '@lowerdeck/hono';
import { v } from '@lowerdeck/validation';
import { db } from '../db';
import { backendSetupHtml } from '../lib/templates/backendSetup';
import { completeDashboardHtml } from '../lib/templates/completeDashboard';
import { scmBackendService, scmInstallationSessionService } from '../services';

export let scmBackendSetupPublicController = createHono()
  .get('/installation-session/:sessionId/setup-backend', async c => {
    let sessionId = c.req.param('sessionId');

    let session = await scmInstallationSessionService.getInstallationSessionPublic({
      sessionId
    });

    let tenant = await db.tenant.findUniqueOrThrow({ where: { oid: session.tenantOid } });

    let setupSession = await scmInstallationSessionService.createBackendSetupSession({
      tenant,
      type: 'github_enterprise',
      parentInstallationSession: session
    });

    return c.html(
      backendSetupHtml({
        sessionId: setupSession.id,
        installationSessionId: session.id
      })
    );
  })
  .get('/backend-setup/:sessionId', async c => {
    let sessionId = c.req.param('sessionId');

    let setupSession = await scmInstallationSessionService.getBackendSetupSessionPublic({
      sessionId
    });

    return c.html(
      backendSetupHtml({
        sessionId: setupSession.id,
        installationSessionId: setupSession.parentInstallationSession?.id
      })
    );
  })
  .post('/backend-setup/:sessionId/complete', async c => {
    let sessionId = c.req.param('sessionId');

    let body = await useValidatedBody(
      c,
      v.object({
        type: v.union([v.literal('github_enterprise'), v.literal('gitlab_selfhosted')]),
        name: v.string(),
        apiUrl: v.string(),
        clientId: v.string(),
        clientSecret: v.string(),
        appId: v.optional(v.string()),
        appSlug: v.optional(v.string()),
        appPrivateKey: [REDACTED]
      })
    );

    let setupSession = await scmInstallationSessionService.getBackendSetupSessionPublic({
      sessionId
    });

    let tenant = await db.tenant.findUniqueOrThrow({ where: { oid: setupSession.tenantOid } });

    // Extract base URL from apiUrl (remove path like /api/v3 or /api/v4)
    let baseUrl = new URL(body.apiUrl);
    baseUrl.pathname = '';
    let webUrl = baseUrl.toString().replace(/\/$/, ''); // Remove trailing slash

    // Add the API path based on provider type
    let apiUrl = body.apiUrl;
    if (body.type === 'github_enterprise' && !apiUrl.includes('/api')) {
      apiUrl = `${apiUrl}/api/v3`;
    } else if (body.type === 'gitlab_selfhosted' && !apiUrl.includes('/api')) {
      apiUrl = `${apiUrl}/api/v4`;
    }

    let backend = await scmBackendService.createScmBackend({
      tenant,
      type: body.type,
      name: body.name,
      description: undefined,
      webUrl,
      apiUrl,
      clientId: body.clientId,
      clientSecret: [REDACTED],
      appId: body.appId,
      appSlug: body.appSlug,
      appPrivateKey: [REDACTED]
    });

    await scmInstallationSessionService.completeBackendSetupSession({
      sessionId,
      backend
    });

    // Determine where to redirect
    if (setupSession.parentInstallationSession) {
      return c.redirect(`/origin/scm/installation-session/${setupSession.parentInstallationSession.id}`);
    }

    if (setupSession.redirectUrl) {
      return c.redirect(setupSession.redirectUrl);
    }

    return c.html(completeDashboardHtml());
  });

import { Paginator } from '@lowerdeck/pagination';
import { v } from '@lowerdeck/validation';
import { scmInstallationPresenter } from '../presenters/scmInstallation';
import { actorService, scmInstallationService } from '../services';
import { app } from './_app';
import { tenantApp } from './tenant';

export let scmInstallationApp = tenantApp.use(async ctx => {
  let scmInstallationId = ctx.body.scmInstallationId;
  if (!scmInstallationId) throw new Error('SCM Installation ID is required');

  let scmInstallation = await scmInstallationService.getScmInstallationById({
    tenant: ctx.tenant,
    scmInstallationId
  });

  return { scmInstallation };
});

export let scmInstallationController = app.controller({
  list: tenantApp
    .handler()
    .input(
      Paginator.validate(
        v.object({
          tenantId: v.string(),
          actorId: v.string()
        })
      )
    )
    .do(async ctx => {
      let actor = await actorService.getActorById({ id: ctx.input.actorId });

      let paginator = await scmInstallationService.listScmInstallations({
        tenant: ctx.tenant,
        actor
      });

      let installations = await paginator.run(ctx.input);

      return Paginator.presentLight(installations, scmInstallationPresenter);
    }),

  get: scmInstallationApp
    .handler()
    .input(
      v.object({
        tenantId: v.string(),
        scmInstallationId: v.string()
      })
    )
    .do(async ctx => scmInstallationPresenter(ctx.scmInstallation))
});

import { badRequestError, notFoundError, ServiceError } from '@lowerdeck/error';
import { Service } from '@lowerdeck/service';
import { randomBytes } from 'crypto';
import type {
  Actor,
  ScmBackend,
  ScmBackendType,
  ScmInstallationSession,
  Tenant
} from '../../prisma/generated/client';
import { db } from '../db';
import { getId } from '../id';

class ScmInstallationSessionServiceImpl {
  async createInstallationSession(d: { tenant: Tenant; actor: Actor; redirectUrl?: string }) {
    let state = randomBytes(32).toString('hex');
    let expiresAt = new Date(Date.now() + 30 * 60 * 1000); // 30 minutes

    return await db.scmInstallationSession.create({
      data: {
        ...getId('scmInstallationSession'),
        tenantOid: d.tenant.oid,
        ownerActorOid: d.actor.oid,
        redirectUrl: d.redirectUrl,
        state,
        expiresAt
      },
      include: { installation: true }
    });
  }

  async getInstallationSession(d: { sessionId: string; tenant: Tenant }) {
    let session = await db.scmInstallationSession.findUnique({
      where: { id: d.sessionId, tenantOid: d.tenant.oid },
      include: { installation: true }
    });

    if (!session) {
      throw new ServiceError(notFoundError('scm_installation_session'));
    }

    if (session.expiresAt < new Date()) {
      throw new ServiceError(badRequestError({ message: 'Installation session expired' }));
    }

    return session;
  }

  async getInstallationSessionPublic(d: { sessionId: string }) {
    let session = await db.scmInstallationSession.findUnique({
      where: { id: d.sessionId },
      include: { tenant: true, installation: true }
    });

    if (!session) {
      throw new ServiceError(notFoundError('scm_installation_session'));
    }

    if (session.expiresAt < new Date()) {
      throw new ServiceError(badRequestError({ message: 'Installation session expired' }));
    }

    return session;
  }

  async getInstallationSessionByState(d: { state: string }) {
    let session = await db.scmInstallationSession.findUnique({
      where: { state: d.state },
      include: { tenant: true, ownerActor: true, installation: true }
    });

    if (!session) {
      throw new ServiceError(notFoundError('scm_installation_session'));
    }

    if (session.expiresAt < new Date()) {
      throw new ServiceError(badRequestError({ message: 'Installation session expired' }));
    }

    return session;
  }

  async completeInstallationSession(d: { sessionId: string; installationOid: bigint }) {
    await db.scmInstallationSession.update({
      where: { id: d.sessionId },
      data: { installationOid: d.installationOid },
      include: { installation: true }
    });
  }

  async createBackendSetupSession(d: {
    tenant: Tenant;
    type: ScmBackendType;
    parentInstallationSession?: ScmInstallationSession;
    redirectUrl?: string;
  }) {
    let state = randomBytes(32).toString('hex');
    let expiresAt = new Date(Date.now() + 30 * 60 * 1000); // 30 minutes

    return await db.scmBackendSetupSession.create({
      data: {
        ...getId('scmBackendSetupSession'),
        tenantOid: d.tenant.oid,
        type: d.type,
        parentInstallationSessionOid: d.parentInstallationSession?.oid,
        redirectUrl: d.redirectUrl,
        state,
        expiresAt
      },
      include: { parentInstallationSession: true, backend: true }
    });
  }

  async getBackendSetupSession(d: { sessionId: string; tenant: Tenant }) {
    let session = await db.scmBackendSetupSession.findUnique({
      where: { id: d.sessionId, tenantOid: d.tenant.oid },
      include: { parentInstallationSession: true, backend: true }
    });

    if (!session) {
      throw new ServiceError(notFoundError('scm_backend_setup_session'));
    }

    if (session.expiresAt < new Date()) {
      throw new ServiceError(badRequestError({ message: 'Backend setup session expired' }));
    }

    return session;
  }

  async getBackendSetupSessionPublic(d: { sessionId: string }) {
    let session = await db.scmBackendSetupSession.findUnique({
      where: { id: d.sessionId },
      include: { parentInstallationSession: true, backend: true }
    });

    if (!session) {
      throw new ServiceError(notFoundError('scm_backend_setup_session'));
    }

    if (session.expiresAt < new Date()) {
      throw new ServiceError(badRequestError({ message: 'Backend setup session expired' }));
    }

    return session;
  }

  async completeBackendSetupSession(d: { sessionId: string; backend: ScmBackend }) {
    await db.scmBackendSetupSession.update({
      where: { id: d.sessionId },
      data: { backendOid: d.backend.oid },
      include: { backend: true }
    });
  }

  async getAvailableBackends(d: { tenant: Tenant }): Promise<ScmBackend[]> {
    return await db.scmBackend.findMany({
      where: {
        OR: [{ isDefault: true, tenantOid: null }, { tenantOid: d.tenant.oid }]
      },
      orderBy: [{ isDefault: 'desc' }, { createdAt: 'asc' }]
    });
  }
}

